if (configFile.error) {
  console.error('readConfig', ts.flattenDiagnosticMessageText(configFile.error.messageText, '\n'));
  process.exit(1);
}
const parsed = ts.parseJsonConfigFileContent(configFile.config, ts.sys, process.cwd());
const program = ts.createProgram({ rootNames: parsed.fileNames, options: parsed.options });
const targetRel = 'src/screens/questionnaire/questionnaire-screen.tsx';
const targetAbs = path.normalize(path.join(process.cwd(), targetRel));
const sf = program.getSourceFile(targetAbs) || program.getSourceFiles().find(f => f.fileName.replace(/\\/g,'/').endsWith(targetRel));
if (!sf) {
  console.log('FILE_NOT_IN_PROGRAM', targetAbs);
  console.log('sample files', program.getSourceFiles().filter(f => f.fileName.includes('questionnaire')).map(f => f.fileName));
  process.exit(2);
}
function printDiags(kind, diags) {
  const rel = diags.filter(d => d.file && path.normalize(d.file.fileName) === path.normalize(sf.fileName));
  console.log('===', kind, 'count', rel.length, '===');
  for (const d of rel) {
    const pos = d.file.getLineAndCharacterOfPosition(d.start);
    console.log(`${kind} TS${d.code} ${d.file.fileName}:${pos.line+1}:${pos.character+1} ${ts.flattenDiagnosticMessageText(d.messageText, '\n')}`);
  }
}
printDiags('syntactic', program.getSyntacticDiagnostics(sf));
printDiags('semantic', program.getSemanticDiagnostics(sf));
printDiags('suggestion', program.getSuggestionDiagnostics(sf));
console.log('covered', sf.fileName);
