() => {
  const pu = window.PgyerUploader;
  const fu = window.forceUploader;
  const describe = (obj) => {
    if (!obj) return null;
    const t = typeof obj;
    if (t === 'function') return {type:'function', length: obj.length, src: Function.prototype.toString.call(obj).slice(0, 500)};
    if (t === 'object') return {type:'object', keys: Object.keys(obj).slice(0, 40)};
    return {type:t, value: String(obj).slice(0,200)};
  };
  return {
    PgyerUploader: describe(pu),
    forceUploader: describe(fu),
    latestPublishAKey: window.latestPublishAKey,
    uploadReadyTxt: window.uploadReadyTxt
  };
}

() => {
  const P = window.PgyerUploader;
  const pending = P.pendingRequest;
  const describePending = pending && typeof pending === 'object' ? {
    keys: Object.keys(pending),
    preview: JSON.stringify(pending, (k,v) => {
      if (typeof v === 'function') return '[fn]';
      if (v && v.name && v.size) return {name:v.name,size:v.size,status:v.status};
      return v;
    }).slice(0,1500)
  } : pending;
  return {
    uploadActive: P.uploadActive,
    awaitingResult: P.awaitingResult,
    uniqueId: P.uniqueId,
    attemptId: P.attemptId,
    pendingRequest: describePending,
    uploaderConfigKeys: P.uploaderConfig ? Object.keys(P.uploaderConfig) : null,
    dropzoneHasFiles: !!(P.dropzone && P.dropzone.files && P.dropzone.files.length),
    initSrc: Function.prototype.toString.call(P.init).slice(0,400),
