() => {
  const P = window.PgyerUploader;
  const u = P.uploaderConfig.currentUploader;
  const file = P.uploaderConfig.currentUploadFile;
  const safeFile = file ? {name:file.name,size:file.size,type:file.type,status:file.status,id:file.id} : null;
  let uploaderInfo = null;
  if (u) {
    uploaderInfo = {
      id: u.id,
      state: typeof u.state === 'function' ? u.state() : u.state,
      files: typeof u.files === 'object' ? Object.keys(u.files||{}).length : null,
      runtime: u.runtime,
      started: u.started
    };
    try {
      const files = u.files || [];
      uploaderInfo.fileList = Array.from(files).map(f => ({name:f.name,size:f.size,status:f.status,percent:f.percent}));
    } catch(e) { uploaderInfo.fileErr = String(e); }
  }
  return {safeFile, currentUploadMethod: P.uploaderConfig.currentUploadMethod, uploaderInfo, uploadActive: P.uploadActive};
}

