    fileList = Array.from(u.files || []).map(f => ({name:f.name,size:f.size,status:f.status,percent:f.percent}));
  } catch (e) {}
  return {isFile, isBlob, addErr, startErr, state: typeof u.state==='function'?u.state():u.state, fileList, filesCount: (u.files&&u.files.length) || 0};
}

