() => {
  const P = window.PgyerUploader;
  if (!P || typeof P.uploadWithOSS !== 'function') return {ok:false, reason:'no uploader'};
  if (P._ossPatched) return {ok:true, already:true};
  const orig = P.uploadWithOSS.bind(P);
  P.uploadWithOSS = function(file) {
    orig(file);
    const startIfNeeded = () => {
      const u = P.uploaderConfig && P.uploaderConfig.currentUploader;
      if (!u || typeof u.addFile !== 'function' || typeof u.start !== 'function') return false;
      const count = u.files ? u.files.length : 0;
      if (count === 0) {
        try { u.addFile(file); } catch (e) {}
        try { u.start(); } catch (e) {}
      } else {
        try { u.start(); } catch (e) {}
      }
      return (u.files && u.files.length > 0);
    };
    setTimeout(startIfNeeded, 500);
    setTimeout(startIfNeeded, 1500);
    setTimeout(startIfNeeded, 3000);
  };
  P._ossPatched = true;
  return {ok:true, already:false, uploadActive: !!P.uploadActive};
}

